from source import fetch_page


def export_rows():
    page = fetch_page()
    status = page["status"]
    rows = page["items"]
    while page["next_cursor"] is not None:
        page = fetch_page(page["next_cursor"])
        rows.extend(page["items"])
    return {"status": status, "rows": rows}

