import unittest

from exporter import export_rows


class ExportTests(unittest.TestCase):
    def test_success_status(self):
        self.assertEqual(200, export_rows()["status"])

    def test_complete_export(self):
        ids = [row["id"] for row in export_rows()["rows"]]
        self.assertEqual(120, len(ids))
        self.assertCountEqual(range(1, 121), ids)


if __name__ == "__main__":
    unittest.main()
